    @Test void exactFiftySourceIntroductionsPreserveTheWholeDocumentExceptSelectedHeadingProperties()throws Exception {
        Map<String,Object> selected=null;try(InputStream in=DraftNativeLayout.class.getResourceAsStream("/drafting/libreoffice-native-layout.json")){assertNotNull(in);Map<String,Object> registry=JsonUtils.mapper().readValue(in,Map.class);for(Object raw:DraftBusinessRules.list(registry.get("sources"))){Map<String,Object> source=DraftBusinessRules.asMap(raw);if("SCC".equals(source.get("key"))){assertNull(selected);selected=source;}}}
        assertNotNull(selected);assertEquals(ORIGINAL_SOURCE_SHA,selected.get("sourceSha256"));List<Object> boundaries=DraftBusinessRules.list(selected.get("paragraphBoundaries"));assertEquals(240,boundaries.size());for(int i=0;i<105;i++)assertFalse(Boolean.TRUE.equals(DraftBusinessRules.asMap(boundaries.get(i)).get("keepBodyLines")),"Legacy source relationships retain their previous body-line policy");List<NativeHeadingFlow> full=allFlows(),additions=introductionFlows();int[][] expected=introductionPairs();assertEquals(50,expected.length);StringBuilder declared=new StringBuilder();Set<String> headings=new LinkedHashSet<>();
        for(int i=0;i<expected.length;i++){int[] pair=expected[i];Map<String,Object> row=DraftBusinessRules.asMap(boundaries.get(105+i));assertEquals(nativeId(pair[0]),row.get("headingId"));assertEquals(nativeId(pair[1]),row.get("bodyId"));assertEquals(Boolean.TRUE,row.get("compactClearedGaps"));assertEquals(Boolean.TRUE,row.get("keepBodyLines"));assertFalse(Boolean.TRUE.equals(row.get("releaseTrailingPageBreak")));List<Object> gaps=DraftBusinessRules.list(row.get("gaps"));assertEquals(1,gaps.size());Map<String,Object> gap=DraftBusinessRules.asMap(gaps.get(0));assertEquals(nativeId(pair[0]+1),gap.get("paragraphId"));assertEquals(pair[0]+2,pair[1]);NativeHeadingFlow flow=additions.get(i);assertEquals(sourceBookmark(pair[0]),flow.getHeadingBookmark());assertEquals(sourceBookmark(pair[1]),flow.getBodyBookmark());assertEquals(1,flow.getEmptyParagraphs());assertTrue(headings.add(flow.getHeadingBookmark()));declared.append(row.get("headingId")).append('|').append(row.get("headingSha256")).append('|').append(row.get("bodyId")).append('|').append(row.get("bodySha256")).append('|').append(gap.get("paragraphId")).append('|').append(gap.get("paragraphSha256")).append('|').append(gap.get("sourceOrdinal")).append("|true\n");}
        assertEquals("80e996b694e73b8ac86bccb52565d693f0c067d3cfdb9bf067955503fa21cc8c",DraftAdoption.hash(declared.toString()),"All fifty complete native declarations, including every source hash and exact gap, stay pinned");
        // Move each verified predecessor chain from its root; nine selected introductions have a verified predecessor after the complete first-item inventory.
        Set<String> expectedRoots=new LinkedHashSet<>(headings);
        for(int[] lifted:new int[][]{{240,238},{270,266},{457,453},{606,594},{1081,1077},{1136,1134},{1172,1170},{1234,1232},{1884,1880}}){assertTrue(expectedRoots.remove(sourceBookmark(lifted[0])));assertTrue(expectedRoots.add(sourceBookmark(lifted[1])));}
        assertEquals(50,expectedRoots.size());assertEquals(expectedRoots,DocxTemplateEditor.nativeHeadingRepairRoots(full,headings),"All fifty exact source introductions repair from their complete verified predecessor roots");
        byte[] original=fixture();DocxEditResult changed=EDITOR.updateNativeHeadingBoundaries(original,DraftPdfConverter.sha256(original),full,headings);String before=xml(original),after=xml(changed.getDocxBytes());assertFalse(before.contains("<w:pageBreakBefore"),"This authored fixture starts without native page boundaries");
        Set<String> endpoints=new LinkedHashSet<>();for(NativeHeadingFlow flow:full){endpoints.add(flow.getHeadingBookmark());endpoints.add(flow.getBodyBookmark());}
        for(String name:endpoints){String prior=paragraph(before,name),next=paragraph(after,name);if(expectedRoots.contains(name)){assertTrue(next.contains("<w:pageBreakBefore w:val=\"1\"/>"),"Verified repair root: "+name);assertEquals(prior,next.replace("<w:pageBreakBefore w:val=\"1\"/>",""),"Only the verified root page boundary may change: "+name);}else assertEquals(prior,next,"All non-root source endpoint paragraphs stay unchanged: "+name);}
        for(int ordinal:new int[]{240,270,457,606,1081,1136,1172,1234,1884})assertEquals(paragraph(before,sourceBookmark(ordinal)),paragraph(after,sourceBookmark(ordinal)),"A lifted introduction keeps its exact original paragraph: "+ordinal);
        int addedBreaks=0;Matcher added=Pattern.compile("<w:pageBreakBefore\\b").matcher(after);while(added.find())addedBreaks++;assertEquals(50,addedBreaks,"No page boundary may be added outside the fifty verified roots");
        assertEquals(before,after.replace("<w:pageBreakBefore w:val=\"1\"/>",""));assertEquals(features(original),features(changed.getDocxBytes()));unchangedPartsExceptDocument(original,changed.getDocxBytes());
    }
    @Test void newlyRegisteredIntroductionsRetainIdentitySelectionDuplicateAndNonemptyGapRejection()throws Exception {
        byte[] original=fixture();List<NativeHeadingFlow> full=allFlows(),additions=introductionFlows();Set<String> selected=new LinkedHashSet<>();for(NativeHeadingFlow flow:additions)selected.add(flow.getHeadingBookmark());assertThrows(EditException.class,()->EDITOR.updateNativeHeadingBoundaries(original,"wrong",full,selected));assertThrows(EditException.class,()->EDITOR.updateNativeHeadingBoundaries(original,DraftPdfConverter.sha256(original),full,Collections.singleton("CSunknownSourceIntroduction")));List<NativeHeadingFlow> duplicate=new ArrayList<>(full);duplicate.add(additions.get(0));assertThrows(EditException.class,()->EDITOR.updateNativeHeadingBoundaries(original,DraftPdfConverter.sha256(original),duplicate,selected));
        int[][] pairs=introductionPairs();for(int ordinal:new int[]{240,339,1234,1353,1402,1442,1687}){int position=-1;for(int i=0;i<pairs.length;i++)if(pairs[i][0]==ordinal)position=i;assertTrue(position>=0);String document=xml(original),gap=paragraph(document,"CLdynamic"+(104+position)+"Gap0");byte[] altered=packageXml(document.replace(gap,gap.replace("</w:p>",text("Unauthorized inserted gap text")+"</w:p>")));assertThrows(EditException.class,()->EDITOR.updateNativeHeadingBoundaries(altered,DraftPdfConverter.sha256(altered),full,selected));}
    }

