    @Test void allNewFirstItemSourceBindingsReuseTheExactExistingNativeFlowContract()throws Exception {
        Map<String,Object> selected=null;try(InputStream in=DraftNativeLayout.class.getResourceAsStream("/drafting/libreoffice-native-layout.json")){Map<String,Object> registry=JsonUtils.mapper().readValue(in,Map.class);for(Object raw:DraftBusinessRules.list(registry.get("sources"))){Map<String,Object> source=DraftBusinessRules.asMap(raw);if("SCC".equals(source.get("key")))selected=source;}}assertNotNull(selected);assertEquals(ORIGINAL_SOURCE_SHA,selected.get("sourceSha256"));List<Object> boundaries=DraftBusinessRules.list(selected.get("paragraphBoundaries"));assertEquals(240,boundaries.size());int[][] expected=additionalFirstItemPairs();assertEquals(85,expected.length);List<NativeHeadingFlow> full=allFlows(),newFlows=full.subList(154,239);Set<String> selectedNames=new LinkedHashSet<>();StringBuilder declared=new StringBuilder();
        for(int i=0;i<expected.length;i++){int[] pair=expected[i];Map<String,Object> row=DraftBusinessRules.asMap(boundaries.get(155+i));assertEquals(nativeId(pair[0]),row.get("headingId"));assertEquals(nativeId(pair[1]),row.get("bodyId"));assertEquals(Boolean.TRUE,row.get("compactClearedGaps"));assertEquals(Boolean.TRUE,row.get("keepBodyLines"));assertFalse(Boolean.TRUE.equals(row.get("releaseTrailingPageBreak")));List<Object> gaps=DraftBusinessRules.list(row.get("gaps"));assertEquals(pair[1]-pair[0]-1,gaps.size());declared.append(row.get("headingId")).append('|').append(row.get("headingSha256")).append('|').append(row.get("bodyId")).append('|').append(row.get("bodySha256")).append("|true|true");for(int g=0;g<gaps.size();g++){Map<String,Object> gap=DraftBusinessRules.asMap(gaps.get(g));assertEquals(nativeId(pair[0]+g+1),gap.get("paragraphId"));declared.append('|').append(gap.get("paragraphId")).append('|').append(gap.get("paragraphSha256"));}declared.append('\n');NativeHeadingFlow flow=newFlows.get(i);assertEquals(sourceBookmark(pair[0]),flow.getHeadingBookmark());assertEquals(sourceBookmark(pair[1]),flow.getBodyBookmark());assertEquals(gaps.size(),flow.getEmptyParagraphs());assertTrue(selectedNames.add(flow.getHeadingBookmark()));}assertEquals("54e10a9d0cb987a44debc8062328e7e77421831c34a9e4bcfb89aadd9c98f003",DraftAdoption.hash(declared.toString()));
        byte[] original=fixture();Set<String> roots=DocxTemplateEditor.nativeHeadingRepairRoots(full,selectedNames);DocxEditResult updated=EDITOR.updateNativeHeadingBoundaries(original,DraftPdfConverter.sha256(original),full,selectedNames);String before=xml(original),after=xml(updated.getDocxBytes());Set<String> endpoints=new LinkedHashSet<>();for(NativeHeadingFlow flow:full){endpoints.add(flow.getHeadingBookmark());endpoints.add(flow.getBodyBookmark());}for(String endpoint:endpoints){String prior=paragraph(before,endpoint),next=paragraph(after,endpoint);if(roots.contains(endpoint)){assertTrue(next.contains("<w:pageBreakBefore w:val=\"1\"/>"));assertEquals(prior,next.replace("<w:pageBreakBefore w:val=\"1\"/>",""));}else assertEquals(prior,next);}assertEquals(before,after.replace("<w:pageBreakBefore w:val=\"1\"/>",""));assertEquals(features(original),features(updated.getDocxBytes()));unchangedPartsExceptDocument(original,updated.getDocxBytes());
        for(int excluded:new int[]{1057,1111})assertFalse(newFlows.stream().anyMatch(flow->sourceBookmark(excluded).equals(flow.getHeadingBookmark())),"Unsupported ordinary line-break source remains outside this contract");
    }
